{
  "name": "obtenir_meteo",
  "description": "Donne la meteo actuelle d'une ville",
  "parameters": {
    "type": "object",
    "properties": {
      "ville": { "type": "string", "description": "Nom de la ville" }
    },
    "required": ["ville"]
  }
}

let messages = [{ role: 'user', content: objectif }]
for (let i = 0; i < MAX_ETAPES; i++) {
  const rep = await modele(messages, outils)
  if (!rep.appelOutil) return rep.texte        // le modele a fini
  const resultat = await executer(rep.appelOutil) // ton code agit
  messages.push(rep, { role: 'tool', content: resultat })
}
throw new Error('Trop d etapes, on arrete') // garde-fou
